body #attract .arcover .aoq{ font-size:calc(var(--fs-label) * var(--attz,1)); color:var(--tx-2); opacity:1; }
/* v28.xx (cw-party-over2): the critic scored screen 55 a 2: "a small, left-aligned box floating in a black void under a competing centred wordmark".
   The wordmark steps out while the run over card is up (the card is the one thing to read), and the card is wider: 840px x scale, the player rows in 20px, one clear block. */
body #attract:has(.arcover[style*="block"]) .attname{ display:none; }
body #attract .arcover{ min-width:calc(var(--menu-w) * 1.5 * var(--attz,1)); }
body #attract .arcover .aor + .aor{ margin-top:calc(var(--sp-1) * var(--attz,1)); }

check:
{v:'VER',what:'the run over card is wide (840px x scale) and the PILLAGERS wordmark steps out while it is up (critic: small box under a competing wordmark, screen 55)',
 run:function(){
   if(typeof arcadeOverEl!=='function'||typeof attEl!=='function') return 'SKIP: no arcade overlay here';
   var d, c, wasDisp, z, res=null, nm, w;
   try{
     __topClear(); __runPrep();
     d=attEl(); wasDisp=d.style.display; d.style.display='block';
     try{ if(typeof attZ==='function') attZ(d); }catch(_z){}
     z=parseFloat(getComputedStyle(d).getPropertyValue('--attz'))||1;
     c=arcadeOverEl(); c.textContent='x'; c.style.display='block';
     nm=d.querySelector('.attname'); w=parseFloat(getComputedStyle(c).width);
     if(getComputedStyle(nm).display!=='none') res='the wordmark still shows over the run over card';
     else if(w<840*z-2) res='the card is only '+w+'px wide, not 840px x '+z;
     c.style.display='none';
     if(!res&&getComputedStyle(nm).display==='none') res='the wordmark stays hidden when the card is gone';
     return res;
   } finally {
     try{ c.style.display='none'; c.textContent=''; c.removeAttribute('data-at'); d.style.display=wasDisp; }catch(_f){}
   }
 }},
